function validate([words, result]) {
  if (!Array.isArray(words) || words.length < 2 || words.length > 5) return 'words needs 2 to 5 strings.';
  for (const text of [...words, result]) {
    if (typeof text !== 'string' || text.length < 1 || text.length > 7) return 'Each word and result has 1 to 7 letters.';
    if (!/^[A-Z]+$/.test(text)) return 'Only uppercase English letters are allowed.';
  }
  if (new Set([...words.join(''), ...result]).size > 10) return 'At most 10 different letters may appear.';
  return null;
}

