function isSolvable(words, result) {
  const weight = new Map();
  const leading = new Set();
  const addWeights = (text, sign) => {
    let place = sign;
    for (let i = text.length - 1; i >= 0; i--) {
      weight.set(text[i], (weight.get(text[i]) ?? 0) + place);
      place *= 10;
    }
    if (text.length > 1) {
      leading.add(text[0]);
    }
  };
  for (const word of words) {
    addWeights(word, 1);
  }
  addWeights(result, -1);

  const letters = [...weight.keys()].sort((a, b) => Math.abs(weight.get(b)) - Math.abs(weight.get(a)));
  const maxRest = new Array(letters.length + 1).fill(0);
  const minRest = new Array(letters.length + 1).fill(0);
  for (let i = letters.length - 1; i >= 0; i--) {
    maxRest[i] = maxRest[i + 1] + Math.max(0, 9 * weight.get(letters[i]));
    minRest[i] = minRest[i + 1] + Math.min(0, 9 * weight.get(letters[i]));
  }
  const used = new Array(10).fill(false);

  function solve(index, total) {
    if (index === letters.length) {
      return total === 0;
    }
    const f = weight.get(letters[index]);
    const ends = f === 0 ? [0, 9] : [(-total - maxRest[index + 1]) / f, (-total - minRest[index + 1]) / f];
    const low = Math.max(leading.has(letters[index]) ? 1 : 0, Math.ceil(Math.min(...ends)));
    const high = Math.min(9, Math.floor(Math.max(...ends)));
    for (let digit = low; digit <= high; digit++) {
      if (!used[digit]) {
        used[digit] = true;
        if (solve(index + 1, total + digit * f)) {
          return true;
        }
        used[digit] = false;
      }
    }
    return false;
  }

  return solve(0, 0);
}

