function isSolvable(words, result) {
  // Add the columns as on paper, from the ones digit up: guess each word's letter,
  // and the result's letter in that column is forced to be the column total mod 10.
  if (words.some(w => w.length > result.length)) return false;
  const firsts = new Set([...words, result].filter(w => w.length > 1).map(w => w[0]));
  const assigned = new Map();
  const taken = new Array(10).fill(false);
  const allowed = (ch, d) => !taken[d] && !(d === 0 && firsts.has(ch));
  const go = (col, row, carry) => {
    if (col === result.length) return carry === 0;
    if (row === words.length) {
      const ch = result[result.length - 1 - col], d = carry % 10;
      if (assigned.has(ch)) return assigned.get(ch) === d && go(col + 1, 0, Math.floor(carry / 10));
      if (!allowed(ch, d)) return false;
      assigned.set(ch, d); taken[d] = true;
      if (go(col + 1, 0, Math.floor(carry / 10))) return true;
      assigned.delete(ch); taken[d] = false;
      return false;
    }
    const w = words[row];
    if (col >= w.length) return go(col, row + 1, carry);
    const ch = w[w.length - 1 - col];
    if (assigned.has(ch)) return go(col, row + 1, carry + assigned.get(ch));
    for (let d = 0; d < 10; d++) {
      if (!allowed(ch, d)) continue;
      assigned.set(ch, d); taken[d] = true;
      if (go(col, row + 1, carry + d)) return true;
      assigned.delete(ch); taken[d] = false;
    }
    return false;
  };
  return go(0, 0, 0);
}

