function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  for (;;) {
    // Random letters over a small alphabet: usually unsolvable.
    if (!large && rand() < 0.3) {
      const alphabet = 'ABCDE'.slice(0, pick(2, 5));
      const word = (length) => Array.from({ length }, () => alphabet[pick(0, alphabet.length - 1)]).join('');
      const words = Array.from({ length: pick(2, 3) }, () => word(pick(1, 3)));
      return [words, word(pick(1, 4))];
    }
    // Build a true addition, then write it in letters.
    const count = large ? pick(3, 5) : pick(2, 3);
    const numbers = Array.from({ length: count }, () => {
      const length = large ? pick(3, 7) : pick(1, 3);
      let value = length === 1 ? pick(0, 9) : pick(1, 9);
      for (let i = 1; i < length; i++) value = value * 10 + pick(0, 9);
      return value;
    });
    const total = numbers.reduce((a, b) => a + b, 0);
    if (total >= 1e7) continue;
    const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
    for (let i = letters.length - 1; i > 0; i--) { const j = pick(0, i); [letters[i], letters[j]] = [letters[j], letters[i]]; }
    const spell = (value) => String(value).split('').map(c => letters[Number(c)]).join('');
    const words = numbers.map(spell);
    let result = spell(total);
    if (rand() < 0.4) {
      // Change one letter of the result to a letter already in use: often breaks the puzzle.
      const used = [...new Set([...words.join(''), ...result])];
      const at = pick(0, result.length - 1);
      result = result.slice(0, at) + used[pick(0, used.length - 1)] + result.slice(at + 1);
    }
    if (!large && new Set([...words.join(''), ...result]).size > 7) continue;
    return [words, result];
  }
}
